hold_ticks := 0
fired := false
if ((#Bedroom #LevelControl).multiButton_button3 == "pushed") {
if (fired == false) {
hold_ticks = hold_ticks + 1
        if (hold_ticks >= 1) {
tmp = (#Bedroom #LevelControl).light_currentBrightness + 5
            if (tmp > 80) {
tmp = 80
}
(#Bedroom #LevelControl).light_moveToBrightness(tmp, 0)
            fired = true
}
}
}
else {
hold_ticks = 0
    fired = false
}

